<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_is_blocked( $blocker_id, $blocked_id ) { global $wpdb; $t = sd_core_table_names(); return (bool) $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$t['blocks']} WHERE blocker_id=%d AND blocked_id=%d LIMIT 1", absint( $blocker_id ), absint( $blocked_id ) ) ); }
function sd_core_block_user( $blocked_id ) { $blocked_id = absint( $blocked_id ); if ( ! is_user_logged_in() || ! $blocked_id || $blocked_id === get_current_user_id() || ! get_userdata( $blocked_id ) ) { return new WP_Error( 'invalid_block', __( 'That member cannot be blocked.', 'social-discovery-core' ), array( 'status' => 400 ) ); } if ( sd_core_is_blocked( get_current_user_id(), $blocked_id ) ) { return true; } global $wpdb; $t = sd_core_table_names(); $result = $wpdb->insert( $t['blocks'], array( 'blocker_id' => get_current_user_id(), 'blocked_id' => $blocked_id, 'created_at' => current_time( 'mysql', true ) ), array( '%d', '%d', '%s' ) ); sd_core_audit( 'member_blocked', 'user', $blocked_id, $result ? 'success' : 'failed' ); return $result ? true : new WP_Error( 'block_failed', __( 'The member could not be blocked.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
function sd_core_unblock_user( $blocked_id ) { global $wpdb; $t = sd_core_table_names(); $result = $wpdb->delete( $t['blocks'], array( 'blocker_id' => get_current_user_id(), 'blocked_id' => absint( $blocked_id ) ), array( '%d', '%d' ) ); sd_core_audit( 'member_unblocked', 'user', $blocked_id, 'success' ); return false !== $result; }
function sd_core_blocked_ids( $user_id = 0 ) { global $wpdb; $t = sd_core_table_names(); return array_map( 'absint', $wpdb->get_col( $wpdb->prepare( "SELECT blocked_id FROM {$t['blocks']} WHERE blocker_id=%d ORDER BY id DESC LIMIT 500", $user_id ? absint( $user_id ) : get_current_user_id() ) ) ); }
